tinymce.PluginManager.add("multiimage", function (editor) {
    editor.ui.registry.addButton("multiimage", {
        text: "Upload Images",
        onAction: function () {
            const input = document.createElement("input");
            input.type = "file";
            input.multiple = true;
            input.accept = "image/*";

            input.onchange = function () {
                const files = input.files;
                if (!files.length) return;

                // 👉 xử lý từng ảnh (QUAN TRỌNG)
                Array.from(files).forEach((file) => {
                    const reader = new FileReader();

                    reader.onload = function (e) {
                        // 👉 tạo popup crop
                        const modal = document.createElement("div");
                        modal.innerHTML = `
                            <div style="
                                position:fixed;top:0;left:0;width:100%;height:100%;
                                background:rgba(0,0,0,0.7);
                                display:flex;align-items:center;justify-content:center;
                                z-index:9999;
                            ">
                                <div style="background:#fff;padding:20px;border-radius:8px;">
                                    <img id="crop-image" src="${e.target.result}" style="max-width:400px;">
                                    <br><br>
                                    <button id="crop-btn">Crop & Upload</button>
                                    <button id="cancel-btn">Cancel</button>
                                </div>
                            </div>
                        `;

                        document.body.appendChild(modal);

                        const image = modal.querySelector("#crop-image");

                        // 👉 khởi tạo cropper
                        let cropper;
                        image.onload = function () {
                            cropper = new Cropper(image, {
                                aspectRatio: NaN,
                                viewMode: 1,
                            });
                        };

                        // 👉 khi bấm crop
                        modal.querySelector("#crop-btn").onclick =
                            async function () {
                                const canvas = cropper.getCroppedCanvas({
                                    width: 300,
                                    height: 300,
                                });

                                canvas.toBlob(async function (blob) {
                                    let formData = new FormData();
                                    formData.append(
                                        "images[]",
                                        blob,
                                        file.name,
                                    );

                                    try {
                                        const res = await fetch(
                                            "/upload-images",
                                            {
                                                method: "POST",
                                                body: formData,
                                                headers: {
                                                    "X-CSRF-TOKEN":
                                                        document.querySelector(
                                                            'meta[name="csrf-token"]',
                                                        ).content,
                                                },
                                            },
                                        );

                                        const data = await res.json();

                                        const url = data.images[0];

                                        // 👉 insert ảnh (GIỐNG CODE CŨ CỦA BẠN)
                                        editor.insertContent(`
                                        <img src="${url}" 
                                             style="width:120px; margin:5px; display:inline-block;" />
                                    `);

                                        editor.selection.collapse(false);
                                        editor.insertContent("&nbsp;");
                                    } catch (err) {
                                        console.error(err);
                                        alert("Upload lỗi!");
                                    }

                                    modal.remove();
                                });
                            };

                        // 👉 cancel
                        modal.querySelector("#cancel-btn").onclick =
                            function () {
                                modal.remove();
                            };
                    };

                    reader.readAsDataURL(file);
                });
            };

            input.click();
        },
    });
});
